function MiniPlayer({ journey, isPlaying, onToggle, onNext, onPrev, progress, duration, onSeek, onClose }) {
  if (!journey) return null;
  const pct = duration ? (progress / duration) * 100 : 0;
  return (
    <div className="mini-player">
      <input
        className="mini-seek"
        type="range"
        min={0}
        max={duration || 0}
        value={Math.min(progress, duration || 0)}
        onChange={(e) => onSeek(Number(e.target.value))}
        style={{ "--pct": `${pct}%` }}
      />
      <div className="mini-row">
        <JourneyThumb journey={journey} size={44} radius={10} />
        <div className="mini-info">
          <div className="mini-title">{journey.title}</div>
          <div className="mini-date">{formatTime(progress)} / {formatTime(duration)}</div>
        </div>
        <button className="icon-btn" onClick={onPrev} aria-label="previous">
          <SkipBack size={18} fill="currentColor" />
        </button>
        <button className="play-btn-sm play-btn-mini" onClick={onToggle} aria-label="play pause">
          {isPlaying ? <Pause size={16} fill="currentColor" /> : <Play size={16} fill="currentColor" style={{ marginLeft: 1 }} />}
        </button>
        <button className="icon-btn" onClick={onNext} aria-label="next">
          <SkipForward size={18} fill="currentColor" />
        </button>
        <button className="icon-btn mini-close" onClick={onClose} aria-label="close player">
          <X size={17} />
        </button>
      </div>
    </div>
  );
}

function TabBar({ tab, setTab }) {
  const tabs = [
    { key: "home", label: "Home" },
    { key: "favorites", label: "Favorites" },
    { key: "roadbook", label: "Roadbook" },
    { key: "about", label: "About" },
  ];
  return (
    <div className="tab-bar">
      {tabs.map((t) => {
        const active = tab === t.key;
        return (
          <button key={t.key} className={`tab-btn ${active ? "tab-active" : ""}`} onClick={() => setTab(t.key)}>
            {t.key === "home" ? (
              <img src={VAN_B64} alt="" className={`tab-van-icon ${active ? "tab-van-active" : "tab-van-inactive"}`} />
            ) : t.key === "favorites" ? (
              <Heart size={21} strokeWidth={active ? 2.2 : 1.8} fill={active ? "currentColor" : "none"} />
            ) : t.key === "roadbook" ? (
              <Map size={21} strokeWidth={active ? 2.2 : 1.8} />
            ) : (
              <Info size={21} strokeWidth={active ? 2.2 : 1.8} />
            )}
            <span className="tab-label">{t.label}</span>
          </button>
        );
      })}
    </div>
  );
}

export default function TheVanApp() {
  const [tab, setTab] = useState("home");
  const [favorites, setFavorites] = useState([]);
  const [currentId, setCurrentId] = useState(null);
  const [openId, setOpenId] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const audioRef = useRef(null);

  const [journeys, setJourneys] = useState(FALLBACK_JOURNEYS);
  const [journeysLoading, setJourneysLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    fetchJourneysFromSheet()
      .then((data) => {
        if (!cancelled && data.length) setJourneys(data);
      })
      .catch((err) => {
        console.error("Could not load live episode list, using fallback:", err);
      })
      .finally(() => {
        if (!cancelled) setJourneysLoading(false);
      });
    return () => { cancelled = true; };
  }, []);

  const currentIndex = journeys.findIndex((j) => j.id === currentId);
  const currentJourney = currentIndex >= 0 ? journeys[currentIndex] : null;

  useEffect(() => {
    if (!audioRef.current) return;
    if (isPlaying) {
      const p = audioRef.current.play();
      if (p && p.catch) p.catch(() => {});
    } else {
      audioRef.current.pause();
    }
  }, [isPlaying, currentId]);

  function handlePlay(id) {
    if (id === currentId) {
      setIsPlaying((p) => !p);
    } else {
      setCurrentId(id);
      setIsPlaying(true);
      setProgress(0);
    }
  }

  function handleNext() {
    if (currentIndex < 0) return;
    const nextIdx = (currentIndex + 1) % journeys.length;
    setCurrentId(journeys[nextIdx].id);
    setIsPlaying(true);
    setProgress(0);
  }

  function handlePrev() {
    if (currentIndex < 0) return;
    const prevIdx = (currentIndex - 1 + journeys.length) % journeys.length;
    setCurrentId(journeys[prevIdx].id);
    setIsPlaying(true);
    setProgress(0);
  }

  function handleFav(id) {
    setFavorites((f) => (f.includes(id) ? f.filter((x) => x !== id) : [...f, id]));
  }

  function handleSeek(t) {
    if (audioRef.current) {
      audioRef.current.currentTime = t;
      setProgress(t);
    }
  }

  function handleClosePlayer() {
    setIsPlaying(false);
    setCurrentId(null);
    setProgress(0);
  }

  return (
    <div className="app-root">
      <style>{CSS}</style>
      <audio
        ref={audioRef}
        src={currentJourney ? currentJourney.audioUrl : undefined}
        onTimeUpdate={(e) => setProgress(e.target.currentTime)}
        onLoadedMetadata={(e) => setDuration(e.target.duration)}
        onEnded={handleNext}
      />
      <div className="screen">
        {tab === "home" && (
          <HomeView journeys={journeys} currentId={currentId} isPlaying={isPlaying} favorites={favorites} onPlay={handlePlay} onFav={handleFav} onOpen={setOpenId} />
        )}
        {tab === "favorites" && (
          <FavoritesView journeys={journeys} favorites={favorites} currentId={currentId} isPlaying={isPlaying} onPlay={handlePlay} onFav={handleFav} onOpen={setOpenId} goHome={() => setTab("home")} />
        )}
        {tab === "roadbook" && <RoadbookView />}
        {tab === "about" && <AboutView />}
      </div>
      {openId != null && (
        <JourneyDetail
          journey={journeys.find((j) => j.id === openId)}
          isCurrent={openId === currentId}
          isPlaying={isPlaying}
          isFav={favorites.includes(openId)}
          onPlay={handlePlay}
          onFav={handleFav}
          onClose={() => setOpenId(null)}
        />
      )}
      <MiniPlayer
        journey={currentJourney}
        isPlaying={isPlaying}
        onToggle={() => setIsPlaying((p) => !p)}
        onNext={handleNext}
        onPrev={handlePrev}
        progress={progress}
        duration={duration}
        onSeek={handleSeek}
        onClose={handleClosePlayer}
      />
      <TabBar tab={tab} setTab={setTab} />
    </div>
  );
}

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@600;700;800&family=Inter:wght@400;500;600&family=Dancing+Script:wght@600;700&display=swap');

:root {
  --bg: #0a0d0b;
  --surface: #121613;
  --surface-2: #1a201c;
  --border: #232b26;
  --accent: #39ACD0;
  --accent-dim: #2C86A6;
  --text: #f4f7f5;
  --text-dim: #93a39a;
  --text-dim2: #5d6a63;
}

* { box-sizing: border-box; }

.app-root {
  max-width: 460px;
  margin: 0 auto;
  min-height: 100vh;
  background: radial-gradient(120% 60% at 50% 0%, #101512 0%, var(--bg) 55%);
  color: var(--text);
  font-family: 'Inter', -apple-system, sans-serif;
  position: relative;
  padding-bottom: 158px;
  overflow-x: hidden;
}

.screen { padding: 28px 20px 12px; }

.fade-in { animation: fadeIn 0.35s ease; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }

.eyebrow {
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--accent);
  margin-bottom: 6px;
}
.eyebrow-center { text-align: center; }

.page-title {
  font-family: 'Poppins', sans-serif;
  font-size: 30px;
  font-weight: 800;
  margin: 0 0 20px;
  letter-spacing: -0.01em;
}
.page-title.center { text-align: center; margin-bottom: 6px; }

.home-logo { height: 34px; width: auto; margin-bottom: 10px; display: block; }

.section-title {
  font-family: 'Poppins', sans-serif;
  font-size: 17px;
  font-weight: 700;
  margin: 26px 0 12px;
}

/* Hero card */
.hero-card {
  position: relative;
  border-radius: 26px;
  min-height: 300px;
  background-size: cover;
  background-position: center;
  border: 1px solid var(--border);
  padding: 18px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: 0 20px 40px -20px rgba(0,0,0,0.6);
}
.hero-badge {
  align-self: flex-start;
  background: rgba(57, 172, 208, 0.16);
  border: 1px solid rgba(57, 172, 208, 0.4);
  color: var(--accent);
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.03em;
  padding: 6px 12px;
  border-radius: 999px;
  backdrop-filter: blur(6px);
}
.hero-bottom {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
}
.hero-text { cursor: pointer; }
.hero-title {
  font-family: 'Poppins', sans-serif;
  font-weight: 700;
  font-size: 19px;
  line-height: 1.25;
  margin-bottom: 4px;
  text-shadow: 0 2px 10px rgba(0,0,0,0.5);
}
.hero-date { font-size: 13px; color: rgba(244,247,245,0.75); }

.play-btn-lg {
  flex-shrink: 0;
  width: 56px; height: 56px;
  border-radius: 50%;
  border: none;
  background: var(--accent);
  color: #06130a;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  box-shadow: 0 8px 24px -6px rgba(57,172,208,0.6);
  transition: transform 0.15s ease;
}
.play-btn-lg:active { transform: scale(0.92); }

/* Episode list */
.ep-list { display: flex; flex-direction: column; gap: 8px; }
.ep-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 10px;
  border-radius: 16px;
  border: 1px solid transparent;
  transition: background 0.15s ease, border-color 0.15s ease;
}
.ep-row-active { background: rgba(57,172,208,0.08); border-color: rgba(57,172,208,0.28); }
.ep-clickable { display: flex; align-items: center; gap: 12px; flex: 1; min-width: 0; cursor: pointer; }
.ep-info { flex: 1; min-width: 0; }
.ep-title { font-size: 14.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ep-date { font-size: 12px; color: var(--text-dim); margin-top: 2px; }

.thumb-fallback {
  display: flex; align-items: center; justify-content: center;
  background: linear-gradient(145deg, var(--surface-2), var(--surface));
  color: var(--text-dim2);
  flex-shrink: 0;
}

.icon-btn {
  background: none; border: none; color: var(--text-dim);
  width: 32px; height: 32px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; flex-shrink: 0;
  transition: color 0.15s ease, background 0.15s ease;
}
.icon-btn:hover { background: var(--surface-2); color: var(--text); }
.heart-btn.heart-active { color: var(--accent); }

.play-btn-sm {
  flex-shrink: 0;
  width: 34px; height: 34px;
  border-radius: 50%;
  border: none;
  background: var(--surface-2);
  color: var(--text);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}
.ep-row-active .play-btn-sm { background: var(--accent); color: #06130a; }

/* Empty state */
.empty-state {
  display: flex; flex-direction: column; align-items: center; text-align: center;
  padding: 60px 20px 30px;
}
.empty-icon-circle {
  width: 68px; height: 68px; border-radius: 50%;
  background: rgba(57,172,208,0.1);
  border: 1px solid rgba(57,172,208,0.25);
  color: var(--accent);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px;
}
.empty-title { font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 17px; margin-bottom: 8px; }
.empty-sub { font-size: 13.5px; color: var(--text-dim); max-width: 240px; line-height: 1.5; margin-bottom: 22px; }
.pill-btn {
  background: var(--accent); color: #06130a; border: none;
  font-weight: 700; font-size: 14px;
  padding: 12px 26px; border-radius: 999px; cursor: pointer;
}

/* Roadbook */
.roadbook-header {
  background: linear-gradient(160deg, #142a1c, #0d1712 70%);
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 30px 20px 24px;
  display: flex; flex-direction: column; align-items: center;
  margin-bottom: 22px;
}
.roadbook-icon {
  width: 52px; height: 52px; border-radius: 50%;
  background: rgba(57,172,208,0.14);
  color: var(--accent);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 14px;
}
.roadbook-sub { font-size: 13.5px; color: var(--text-dim); text-align: center; margin-top: 2px; }
.roadbook-body {
  border-left: 2px solid var(--accent);
  padding-left: 16px;
  display: flex; flex-direction: column; gap: 16px;
}
.roadbook-p { font-size: 14.5px; line-height: 1.7; color: rgba(244,247,245,0.88); margin: 0; }
.roadbook-signature {
  font-family: 'Dancing Script', cursive;
  font-weight: 700;
  font-size: 34px;
  letter-spacing: 0.04em;
  color: var(--accent);
  text-align: right;
  margin-top: 18px;
  padding-right: 8px;
  transform: rotate(-3deg);
}

/* About */
.about-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 28px 20px 22px;
  display: flex; flex-direction: column; align-items: center;
  text-align: center;
  margin-bottom: 24px;
}
.about-logo {
  width: 84px; height: 84px; border-radius: 50%;
  object-fit: cover;
  border: 2px solid var(--accent);
  margin-bottom: 16px;
  box-shadow: 0 8px 24px -8px rgba(57,172,208,0.5);
}
.about-text { font-size: 14px; line-height: 1.7; color: rgba(244,247,245,0.85); max-width: 340px; }

.connect-list { display: flex; flex-direction: column; gap: 8px; }
.connect-row {
  display: flex; align-items: center; gap: 12px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 13px 14px;
  text-decoration: none;
  color: var(--text);
  transition: background 0.15s ease;
}
.connect-row:hover { background: var(--surface-2); }
.connect-icon {
  width: 34px; height: 34px; border-radius: 50%;
  background: rgba(57,172,208,0.12); color: var(--accent);
  display: flex; align-items: center; justify-content: center; flex-shrink: 0;
}
.connect-text { flex: 1; display: flex; flex-direction: column; }
.connect-label { font-size: 14px; font-weight: 600; }
.connect-sub { font-size: 12px; color: var(--text-dim); margin-top: 1px; }
.connect-chevron { color: var(--text-dim2); }

/* Mini player */
.mini-player {
  position: fixed;
  bottom: 74px;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  max-width: 460px;
  background: rgba(18,22,19,0.92);
  backdrop-filter: blur(14px);
  border-top: 1px solid var(--border);
  padding: 10px 14px 8px;
  z-index: 20;
}
.mini-seek {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 3px;
  border-radius: 2px;
  background: linear-gradient(to right, var(--accent) var(--pct), var(--surface-2) var(--pct));
  outline: none;
  margin-bottom: 10px;
  cursor: pointer;
}
.mini-seek::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 11px; height: 11px; border-radius: 50%;
  background: var(--accent);
  cursor: pointer;
}
.mini-seek::-moz-range-thumb {
  width: 11px; height: 11px; border-radius: 50%;
  background: var(--accent); border: none; cursor: pointer;
}
.mini-row { display: flex; align-items: center; gap: 10px; }
.mini-info { flex: 1; min-width: 0; }
.mini-title { font-size: 13.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mini-date { font-size: 11px; color: var(--text-dim); margin-top: 1px; }
.play-btn-mini { background: var(--accent); color: #06130a; }
.mini-close { width: 30px; height: 30px; flex-shrink: 0; }

/* Tab bar */
.tab-bar {
  position: fixed;
  bottom: 0; left: 50%; transform: translateX(-50%);
  width: 100%; max-width: 460px;
  background: rgba(10,13,11,0.96);
  backdrop-filter: blur(14px);
  border-top: 1px solid var(--border);
  display: flex;
  padding: 10px 6px calc(10px + env(safe-area-inset-bottom));
  z-index: 21;
}
.tab-btn {
  flex: 1;
  background: none; border: none;
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  color: var(--text-dim2);
  font-family: 'Inter', sans-serif;
  cursor: pointer;
  padding: 4px 0;
  transition: color 0.15s ease;
}
.tab-btn.tab-active { color: var(--accent); }
.tab-label { font-size: 10.5px; font-weight: 600; }
.tab-van-icon {
  width: 22px; height: 22px; border-radius: 7px;
  object-fit: cover;
  transition: filter 0.2s ease, opacity 0.2s ease, box-shadow 0.2s ease;
}
.tab-van-inactive { filter: grayscale(1) brightness(0.75); opacity: 0.75; }
.tab-van-active { filter: none; opacity: 1; box-shadow: 0 0 0 2px var(--accent); }

/* Journey detail overlay */
.detail-overlay {
  position: fixed;
  inset: 0;
  max-width: 460px;
  margin: 0 auto;
  background: var(--bg);
  z-index: 40;
  overflow-y: auto;
}
.detail-hero {
  position: relative;
  height: 300px;
  background-size: cover;
  background-position: center;
}
.detail-hero-fade {
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(10,13,11,0.1) 0%, rgba(10,13,11,0.2) 55%, var(--bg) 100%);
}
.detail-close {
  position: absolute;
  top: 18px; left: 18px;
  width: 38px; height: 38px;
  border-radius: 50%;
  background: rgba(10,13,11,0.55);
  backdrop-filter: blur(6px);
  border: 1px solid rgba(255,255,255,0.12);
  color: var(--text);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
}
.detail-body { padding: 18px 22px 40px; margin-top: -34px; position: relative; }
.detail-top {
  display: flex; align-items: flex-end; justify-content: space-between;
  gap: 14px; margin-bottom: 20px;
}
.detail-title { font-family: 'Poppins', sans-serif; font-weight: 800; font-size: 22px; line-height: 1.25; }
.detail-date { font-size: 13px; color: var(--text-dim); margin-top: 5px; }
.detail-actions { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }
.detail-heart {
  width: 44px; height: 44px;
  border: 1px solid var(--border);
  background: var(--surface);
}
.detail-description { font-size: 14.5px; line-height: 1.75; color: rgba(244,247,245,0.88); white-space: pre-line; }
`;
